/*
    Quick implementation of what I call "cyclic noise" in it's simplest 2D form
    For people who want to play with it! Let me know what you make :)

    The rotation matrix angle can be changed for various flow style. 
    From more organic, to more "electric", included a couple to show the difference.
*/

float cyclic2D(vec2 p)
{
    mat2 m2 = mat2(0.97367, 0.22798, -0.22798, 0.97367)*1.5;
    //mat2 m2 = mat2(0.88233, 0.47063, -0.47063, 0.88233)*1.5;
    float result = 0.;
    float z = .95;
    float distort = 2.1;
    float dstAmount = 0.09;
    for(int i = 0; i < 9; i++)
    {
		p += sin(p.yx*distort + iTime*0.27*pow(distort,1.35))*dstAmount;
        result += abs(dot(cos(p), sin(p))*z);
        z *= 0.65;
        distort *= 1.35;
        p = p*m2;
    }
    return result;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = (gl_FragCoord.xy - 0.5*iResolution.xy)/iResolution.y + iTime*0.015;

    vec3 col = vec3(sin(vec3(1.15,1.65,2.25)*cyclic2D(p*4.3) + 4.2))*0.5+0.5;
    fragColor = vec4(.05/(col*col+0.05), 1);
}

